// js/beats.js - v3 story beats, one per journey stop (126).
// Authored and gated against the audited layer: node check-beats.js
// shape: window.UNPACKED_BEATS[stopId] = { h, b, stat: {v,u,l}, call: [{x,y,label,sub},{..}] }
window.UNPACKED_BEATS = {
  "keyboard-room": {"h":"The Room","b":"One desk. One lamp. Nineteen ordinary things. Every one of them climbed out of a pit somewhere. Tonight we pick the keyboard and ride it to the bottom.","stat":{"v":"9","u":"stops","l":"we end in a crude oil well"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "keyboard-01": {"h":"A Keyboard","b":"Eighty-seven switches. Every key a machine with its own spring, stem and two gold-coated fingers. Not one part of it came from the same place.","stat":{"v":"87","u":"keys","l":"tiny machines, one per letter"},"call":[{"x":30,"y":44,"label":"Keycaps","sub":"molded plastic"},{"x":64,"y":56,"label":"Switches","sub":"one per key"}]},
  "keyboard-spring-01": {"h":"The Spring","b":"Under your key, a coil of steel wound thinner than a hair. Pressed fifty million times and it still answers on the first try. The click is this spring, buckling.","stat":{"v":"0.2","u":"mm","l":"steel wire, hair-thin"},"call":[{"x":34,"y":44,"label":"Music wire","sub":"thinner than hair"},{"x":64,"y":56,"label":"The coil","sub":"wound by machine"}]},
  "keyboard-switch-01": {"h":"The Switch","b":"Nine parts and one job: press it and a stem walks down a spring until two gold fingers kiss. One millisecond of contact. That is the whole message.","stat":{"v":"1","u":"ms","l":"the kiss that types your letter"},"call":[{"x":42,"y":64,"label":"The stem","sub":"pressed 45 cN down"},{"x":82,"y":38,"label":"Contacts","sub":"two gold fingers"}]},
  "keyboard-keycap-01": {"h":"The Keycap","b":"A hollow shell of ABS with walls thinner than a coin, warm out of a steel mold. The letter on top gets printed on, one dot of ink at a time.","stat":{"v":"1.2","u":"mm","l":"of plastic wall"},"call":[{"x":36,"y":44,"label":"The shell","sub":"1.2 mm thin"},{"x":64,"y":56,"label":"The letter","sub":"pad printed"}]},
  "keyboard-inj-02": {"h":"The Press","b":"Two steel halves slam shut under eighty tons, glowing melted plastic floods the cavities, and thirty seconds later a batch of caps drops out. On loop, all week.","stat":{"v":"80","u":"tons","l":"of squeeze per shot"},"call":[{"x":38,"y":50,"label":"The clamp","sub":"80 tons of squeeze"},{"x":64,"y":27,"label":"The hopper","sub":"pellets feed the melt"}]},
  "keyboard-mold-tooling": {"h":"The Mold","b":"Before any cap exists, toolmakers carve its negative into tool steel and polish the cavity to a mirror. Carve it once and it prints a million letters.","stat":{"v":"0.05","u":"mm","l":"how true the cavity must be"},"call":[{"x":34,"y":44,"label":"The cavity","sub":"polished by hand"},{"x":64,"y":56,"label":"Parting line","sub":"where halves meet"}]},
  "keyboard-abs-03": {"h":"Plastic Pellets","b":"Caps begin as lentil-sized beads of ABS. Warm them and they run like honey; cool them and they hold shape forever. Same stuff as your LEGO.","stat":{"v":"220","u":"°C","l":"the melt where pellets turn liquid"},"call":[{"x":34,"y":44,"label":"The pellet","sub":"solid plastic"},{"x":64,"y":56,"label":"Melted","sub":"flows like honey"}]},
  "keyboard-petroleum-04": {"h":"The Ground","b":"Crude oil from three kilometers down becomes naphtha becomes ABS becomes your keycap. First well was drilled in 1859. Everything plastic in this room ends here.","stat":{"v":"3,000","u":"m","l":"depth of the well it came from"},"call":[{"x":30,"y":36,"label":"The derrick","sub":"drills down"},{"x":62,"y":52,"label":"Crude oil","sub":"the raw stuff"}]},
  "desk-lamp-room": {"h":"The Room","b":"One lamp giving 450 lumens and asking nothing back. Ride its glow backward and the light goes out through aluminum bars into red dirt.","stat":{"v":"6","u":"stops","l":"we end in a bauxite mine"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "desk-lamp-01": {"h":"A Desk Lamp","b":"A head of 28 light crystals that holds whatever angle you leave it in. Twenty-five years of night shifts without a flicker.","stat":{"v":"450","u":"lm","l":"of warm 400K light"},"call":[{"x":34,"y":38,"label":"The head","sub":"where light comes out"},{"x":64,"y":52,"label":"The arm","sub":"holds any pose"}]},
  "desk-lamp-head-01": {"h":"The Lamp Head","b":"Twenty-eight crystals sit on a strip of aluminum behind one plastic lens. The lens melts the dots into one wash of light; the aluminum drinks the heat away.","stat":{"v":"28","u":"","l":"crystals behind one lens"},"call":[{"x":38,"y":42,"label":"The lens","sub":"spreads the dots"},{"x":64,"y":58,"label":"Aluminum board","sub":"carries heat off"}]},
  "desk-lamp-smt-02": {"h":"The Placement Line","b":"A pick-and-place head sets forty-five thousand crystals an hour, each one within a hair of its mark, then an oven bakes the board so none of them ever moves again.","stat":{"v":"45,000","u":"per hour","l":"placed to 0.05 mm"},"call":[{"x":28,"y":40,"label":"The head","sub":"picks and sets"},{"x":58,"y":54,"label":"The oven","sub":"bakes it solid"}]},
  "desk-lamp-mcpcb-03": {"h":"The Aluminum Board","b":"LEDs run hot, so they live on metal instead of fiberglass: copper traces etched on a brushed-aluminum core. The heat has somewhere to go, so the light outlives you.","stat":{"v":"2.0","u":"W/mK","l":"heat running straight through the base"},"call":[{"x":34,"y":46,"label":"Copper circuit","sub":"carries current"},{"x":64,"y":56,"label":"Aluminum base","sub":"carries heat"}]},
  "desk-lamp-bauxite-04": {"h":"The Ground","b":"The aluminum began as red dirt in a thirty-meter pit, purified by electricity on a heroic scale. Your lamp ends here, in pocked, porous ore.","stat":{"v":"45","u":"%","l":"of this dirt is alumina, the lamp's ancestor"},"call":[{"x":42,"y":44,"label":"The core","sub":"unweathered, and hard"},{"x":70,"y":28,"label":"The skin","sub":"pocked, porous"}]},
  "office-chair-room": {"h":"The Room","b":"A chair that holds you all day without a word of complaint. Under the mesh sit two industries, plastic and steel, meeting on one post.","stat":{"v":"6","u":"stops","l":"we end in a crude oil well"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "office-chair-01": {"h":"An Office Chair","b":"113 kg held all day, a 120-degree lean on request, five wheels taking your weight for granted. None of it announces itself. That was the brief.","stat":{"v":"113","u":"kg","l":"held up all day"},"call":[{"x":36,"y":38,"label":"Mesh back","sub":"woven nylon"},{"x":64,"y":54,"label":"Gas cylinder","sub":"lifts the seat"}]},
  "office-chair-base-01": {"h":"The Five-Star Base","b":"Five hollow legs of nylon stiffened with glass fiber, blown out with gas so they take a grown adult without adding weight. Your seatpost screws right into its heart.","stat":{"v":"640","u":"mm","l":"leg-span across the floor"},"call":[{"x":48,"y":34,"label":"Gas cylinder","sub":"sets the height"},{"x":28,"y":62,"label":"A leg","sub":"hollow inside"}]},
  "office-chair-injection-02": {"h":"The Mold","b":"Melt nylon, fill a star-shaped mold, then blow nitrogen in to hollow the thick parts. Three hundred tons of clamp, 150 bar of gas, one base every 75 seconds.","stat":{"v":"300","u":"tons","l":"of clamp squeeze"},"call":[{"x":48,"y":56,"label":"The cavity","sub":"one base every 75 s"},{"x":77,"y":40,"label":"The part","sub":"ejected, still warm"}]},
  "office-chair-pa-03": {"h":"Glass-Filled Nylon","b":"Chopped glass stirred into nylon 66, first cooked up by DuPont in 1935. Glass stops the sag, nylon stops the snap. You are sitting on that compromise.","stat":{"v":"30","u":"%","l":"chopped glass in the plastic"},"call":[{"x":34,"y":46,"label":"Glass fibers","sub":"chopped to bits"},{"x":64,"y":56,"label":"Nylon","sub":"melts into the mold"}]},
  "office-chair-petroleum-04": {"h":"The Ground","b":"Fabric, base, wheels: all of it is oil, rearranged into furniture. This is the same well that ends the keyboard's chain, three kilometers of history pressed into pellets.","stat":{"v":"1859","u":"","l":"first commercial oil well"},"call":[{"x":30,"y":36,"label":"The derrick","sub":"drills down"},{"x":62,"y":52,"label":"The refinery","sub":"splits the oil"}]},
  "ceramic-mug-room": {"h":"The Room","b":"This mug holds boiling coffee behind a wall four millimeters thin. The trick that lets it do that is a small kiln's worth of fire, running since the Tang dynasty.","stat":{"v":"6","u":"stops","l":"we end in a kaolin mine"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "ceramic-mug-01": {"h":"A Ceramic Mug","b":"It was mud once. Fire turned it to stone, twice over, so your coffee has nowhere to leak. The recipe is a thousand years old and it still works.","stat":{"v":"350","u":"ml","l":"held by a 4 mm wall of stone"},"call":[{"x":54,"y":66,"label":"The wall","sub":"4 mm of stone"},{"x":47,"y":46,"label":"The glaze","sub":"melted glass coating"}]},
  "ceramic-mug-body-01": {"h":"The Clay Body","b":"Shaped on a spinning plaster mold, dried slowly, then fired twice: once at 900 °C to turn it hard, once at 1250 °C to melt glass over its skin. Skip either firing and it's just a cup that soaks.","stat":{"v":"1,250","u":"°C","l":"the fire that turns clay to stone"},"call":[{"x":32,"y":42,"label":"Bisque cup","sub":"fired once, hard"},{"x":64,"y":54,"label":"Kiln shelf","sub":"into the heat"}]},
  "ceramic-mug-pugmill-02": {"h":"The Pugmill","b":"Before shaping, this machine drags clay through a vacuum and pulls every trapped bubble out. One invisible air pocket would burst in the kiln and crack the mug in half.","stat":{"v":"200","u":"kg/hr","l":"de-aired under near-vacuum"},"call":[{"x":34,"y":44,"label":"The auger","sub":"drags the clay"},{"x":64,"y":56,"label":"Vacuum","sub":"sucks the air out"}]},
  "ceramic-mug-kaolin-03": {"h":"Kaolin Clay","b":"Rock, eaten into a powder by a million years of weather, so fine it feels like cream. A trace of iron would brown it, so it gets washed until the iron is under 0.5 percent.","stat":{"v":"2","u":"µm","l":"grain size, cream-fine"},"call":[{"x":54,"y":24,"label":"The kaolin","sub":"rock, rotted to cream"},{"x":38,"y":64,"label":"The whiteness","sub":"iron, washed away"}]},
  "ceramic-mug-kaolinmine-04": {"h":"The Ground","b":"Kaolin is granite rotting in place: hills of it, dug out and washed with water until only white clay is left. The mug's whiteness starts as gray rock on a hillside.","stat":{"v":"90","u":"%","l":"pure clay left after the wash"},"call":[{"x":30,"y":38,"label":"The pit","sub":"white clay benches"},{"x":62,"y":54,"label":"Wash pond","sub":"sand sinks away"}]},
  "steel-desk-room": {"h":"The Room","b":"Quiet, rigid, and entirely mined. Pull on the top of this desk and you arrive at a furnace and a pit one hundred meters deep.","stat":{"v":"6","u":"stops","l":"we end in an iron ore mine"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "steel-desk-01": {"h":"A Steel Desk","b":"One sheet of cold-rolled steel, folded and welded into something you can pile seventeen years of junk on. The 1920s invented this desk and most of those are still standing.","stat":{"v":"1200","u":"mm","l":"top cut from one steel sheet"},"call":[{"x":32,"y":44,"label":"Steel top","sub":"one thin sheet"},{"x":64,"y":56,"label":"Steel legs","sub":"welded tube"}]},
  "steel-desk-top-01": {"h":"The Desktop","b":"A 1.2 mm sheet would bend like a ruler if it were flat. So the press stamps ribs into it: the ribs tell the steel where it's allowed to flex and where it absolutely may not.","stat":{"v":"1.2","u":"mm","l":"sheet, stiffened by its own ribs"},"call":[{"x":34,"y":46,"label":"The ribs","sub":"stiffen the sheet"},{"x":64,"y":56,"label":"Powder coat","sub":"baked-on paint"}]},
  "steel-desk-press-02": {"h":"The Stamping Press","b":"Two hundred tons of press walk the steel through ten die stations at sixty strokes a minute. A coil goes in one side; desktops and drawer boxes come out the other.","stat":{"v":"200","u":"tons","l":"pressing sixty times a minute"},"call":[{"x":45,"y":62,"label":"The draw","sub":"ten dies later"},{"x":56,"y":30,"label":"One a second","sub":"sixty strokes a minute"}]},
  "steel-desk-spcc-03": {"h":"Steel Coil","b":"This coil was molten this morning somewhere. Rolled cold until it's smooth enough to paint straight onto, it arrives as a matte gray skin a millimeter and a bit thick.","stat":{"v":"270","u":"MPa","l":"before the steel gives up"},"call":[{"x":30,"y":36,"label":"The tap","sub":"molten steel pours"},{"x":62,"y":52,"label":"The ladle","sub":"carries the melt"}]},
  "steel-desk-ironore-04": {"h":"The Ground","b":"Rock that is 62 percent iron, dug from terraced pits a hundred meters down and fed to blast furnaces. Every quiet desk in the world is this red dirt, rearranged.","stat":{"v":"62","u":"%","l":"iron in what you're writing on"},"call":[{"x":30,"y":38,"label":"The benches","sub":"terraced steps"},{"x":62,"y":54,"label":"Haul truck","sub":"carries the ore"}]},
  "glass-window-room": {"h":"The Room","b":"Daylight comes through four millimeters of glass that nobody ever polished. It was floated on molten metal and gravity did all the finishing.","stat":{"v":"6","u":"stops","l":"we end in a sand quarry"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "glass-window-01": {"h":"A Glass Window","b":"Dead flat, not because anyone ground it flat, but because it floated out of a liquid metal bath and came off with no scratch on it. Now it just holds the sky in place.","stat":{"v":"4","u":"mm","l":"of glass, never touched by a tool"},"call":[{"x":28,"y":42,"label":"Aluminum frame","sub":"holds the glass"},{"x":64,"y":54,"label":"The pane","sub":"4 mm, dead flat"}]},
  "glass-window-pane-01": {"h":"The Pane","b":"Glass melts glowing at 1550 °C, spills onto a bath of molten tin, and spreads flat under its own weight. Pilkington worked this out in 1952 and it took over the world.","stat":{"v":"1,550","u":"°C","l":"the melt that lets glass float"},"call":[{"x":34,"y":44,"label":"The edge","sub":"4 mm thick"},{"x":64,"y":56,"label":"The face","sub":"never touched"}]},
  "glass-window-float-02": {"h":"The Float Bath","b":"For eight meters the soft ribbon rides a sea of molten tin. Nothing touches it, nothing bends it, and it cools off with a face no polishing wheel could match.","stat":{"v":"3.2","u":"m","l":"of ribbon riding liquid tin"},"call":[{"x":30,"y":40,"label":"Tin bath","sub":"a lake of metal"},{"x":62,"y":54,"label":"Glass ribbon","sub":"floating, still soft"}]},
  "glass-window-soda-03": {"h":"The Glass Batch","b":"Three-quarters sand, a sixth soda ash, some lime. The recipe is basically ancient Rome's: sand to make glass, soda so it doesn't take forever melting, lime so rain can't dissolve it.","stat":{"v":"72","u":"%","l":"of the batch is ordinary quartz sand"},"call":[{"x":42,"y":50,"label":"Silica sand","sub":"72% of the mix"},{"x":86,"y":94,"label":"100 µm","sub":"one grain, measured"}]},
  "glass-window-sand-04": {"h":"The Ground","b":"Quartz sand washed until it's 98 percent pure. Let a speck of iron through and every pane turns green, so the quarry washes and washes and washes.","stat":{"v":"0.03","u":"%","l":"iron allowed, or the glass goes green"},"call":[{"x":30,"y":38,"label":"The sand","sub":"almost pure silica"},{"x":62,"y":54,"label":"Stockpile","sub":"washed and graded"}]},
  "hardcover-book-room": {"h":"The Room","b":"Nobody's opened this book in weeks. Somewhere in its 336 pages there is a forest, a machine, and nine grams of oil. Pick it up.","stat":{"v":"6","u":"stops","l":"we end in a spruce forest"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "hardcover-book-01": {"h":"A Hardcover Book","b":"336 pages of pressed forest, sewn in quires and cased in cloth over cardboard. Pick it up and the whole thing opens flat, like it was made to.","stat":{"v":"640","u":"g","l":"casing 336 sewn pages"},"call":[{"x":34,"y":42,"label":"The boards","sub":"leather over binder's board"},{"x":64,"y":60,"label":"The lettering","sub":"gold foil on leather"}]},
  "hardcover-book-pages-01": {"h":"The Page Block","b":"Twenty-one folded signatures, sewn through every fold with linen thread. Egyptian binders used the same stitch two thousand years ago, and it is why this book opens flat.","stat":{"v":"21","u":"signatures","l":"sewn through every fold"},"call":[{"x":36,"y":40,"label":"The fan","sub":"336 pages loose"},{"x":62,"y":58,"label":"The headband","sub":"woven into the fold"}]},
  "hardcover-book-press-02": {"h":"The Press","b":"Your whole book printed at ten meters a second: water pins the ink to its spot, four rollers lay down CMYK, and the pages are done before your coffee cools.","stat":{"v":"10","u":"m/s","l":"full CMYK at full speed"},"call":[{"x":32,"y":44,"label":"The press line","sub":"dampen, ink, print"},{"x":64,"y":58,"label":"The rolls","sub":"nine tonnes of paper"}]},
  "hardcover-book-paper-03": {"h":"The Paper","b":"It arrives as five-kilometer rolls, clay-coated, 90 grams a square meter. Each page is a tenth of a millimeter of boiled forest fiber.","stat":{"v":"0.1","u":"mm","l":"one page, boiled forest fiber"},"call":[{"x":34,"y":54,"label":"One reel","sub":"5 km of paper"},{"x":64,"y":40,"label":"The web","sub":"feeds the press"}]},
  "hardcover-book-forest-04": {"h":"The Ground","b":"Eighty years of spruce, felled and chipped where it stood. One tree becomes about sixty books like this one. Every page you haven't read yet is standing in this pile.","stat":{"v":"60","u":"","l":"books out of one tree"},"call":[{"x":34,"y":46,"label":"The logs","sub":"80 years of growth"},{"x":64,"y":60,"label":"The forest","sub":"replanted after"}]},
  "ceiling-fan-room": {"h":"The Room","b":"Look up. Two fans spin all day and nobody thanks them. In each one hides a coil of copper and five kilos of steel, and all of it started as red rock.","stat":{"v":"7","u":"stops","l":"we end in a copper mine"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "ceiling-fan-01": {"h":"A Ceiling Fan","b":"Nine steel blades turn 250 times a minute over your head, sixty watts, all afternoon, in silence. Philip Diehl bolted his sewing-machine motor to the ceiling in the 1880s and the design never moved.","stat":{"v":"250","u":"rpm","l":"silent over your head"},"call":[{"x":34,"y":42,"label":"The blades","sub":"nine, matched in pitch"},{"x":64,"y":58,"label":"The motor","sub":"copper inside"}]},
  "ceiling-fan-motor-01": {"h":"The Motor","b":"Eleven hundred turns of enameled copper wound on a laminated steel core. Household current makes the field drag the rotor around, no brushes, nothing to wear out.","stat":{"v":"0.4","u":"kg","l":"of copper in the windings"},"call":[{"x":34,"y":46,"label":"The windings","sub":"enameled copper"},{"x":64,"y":56,"label":"The core","sub":"iron, laminated"}]},
  "ceiling-fan-hardware-01": {"h":"The Fasteners","b":"Seven kilograms of motor and blades hang from one hook in the joist and a handful of M8 bolts, torqued to 18 newton meters. The thread is rolled instead of cut, which is why it never strips.","stat":{"v":"18","u":"Nm","l":"holding 7 kg up for thirty years"},"call":[{"x":57,"y":14,"label":"The hex","sub":"18 newton meters live here"},{"x":56,"y":68,"label":"The thread","sub":"rolled, not cut"}]},
  "ceiling-fan-stamping-02": {"h":"The Stamping Press","b":"Blades are born in one press stroke: blank, bend, flange, pitch accurate to half a degree. Sixty tons of press, forty strokes a minute, and every blade sits in the same pose.","stat":{"v":"60","u":"t","l":"stamping 40 blades a minute"},"call":[{"x":45,"y":62,"label":"The bend","sub":"curved in the stroke"},{"x":56,"y":30,"label":"Same pose","sub":"forty blades a minute"}]},
  "ceiling-fan-magwire-03": {"h":"Enameled Copper Wire","b":"Copper drawn to a third of a millimeter, lacquered orange, 99.99 percent pure. A thousand turns can sit side by side and never let electricity jump.","stat":{"v":"0.31","u":"mm","l":"wire, lacquered orange"},"call":[{"x":34,"y":44,"label":"The wire","sub":"0.31 mm, orange"},{"x":64,"y":58,"label":"The enamel","sub":"keeps turns apart"}]},
  "ceiling-fan-copper-04": {"h":"The Ground","b":"Rock barely worth the drilling: a tonne of it carries under one percent metal. One hundred twenty-five kilos of rock fed a single kilogram of what hums over your bed. This is the hole under the hum.","stat":{"v":"125","u":"kg","l":"of rock for one kilo of copper"},"call":[{"x":30,"y":40,"label":"The benches","sub":"900 m down"},{"x":62,"y":56,"label":"The ore","sub":"one percent copper"}]},
  "candle-room": {"h":"The Room","b":"A flame lives behind the daybed, under its glass hat. Wax from a refinery, cotton from a field, glass from a pit of washed sand. Follow it down.","stat":{"v":"7","u":"stops","l":"we end in a sand quarry"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "candle-01": {"h":"A Candle","b":"Two hundred grams of refined crude oil, stood on end around a cotton braid. It burns forty-five hours at eight hundred fifty degrees and lights one room honestly.","stat":{"v":"45","u":"h","l":"of flame per burn"},"call":[{"x":37,"y":27,"label":"The flame","sub":"850 °C"},{"x":37,"y":44,"label":"The wax","sub":"200 g, food grade"}]},
  "candle-wax-01": {"h":"The Wax Body","b":"This is the part of crude oil that never made it into an engine: boiled off last, dewaxed out of lubricating oil, filtered white. Lit, it melts at fifty-eight degrees, and the pool feeds the wick. The candle eats its own fuel.","stat":{"v":"58","u":"°C","l":"where the pool feeds the wick"},"call":[{"x":34,"y":44,"label":"The pool","sub":"melts at 58 °C"},{"x":64,"y":58,"label":"The column","sub":"cast, not carved"}]},
  "candle-chimney-01": {"h":"The Glass Chimney","b":"One blown piece of soda-lime, a millimeter and a bit thick, with no seam for the flame to find. Argand put glass on lamps in 1784 and the flame doubled its light, and the ceilings of Europe stopped smoking.","stat":{"v":"1,100","u":"°C","l":"hot enough to blow the hat"},"call":[{"x":32,"y":40,"label":"The chimney","sub":"glows around the flame"},{"x":64,"y":56,"label":"One-piece glass","sub":"no seam to crack"}]},
  "candle-blow-02": {"h":"The Blow Machine","b":"A 180-gram gob comes off the furnace glowing. One puff settles it, one blow opens it to gauge against hot mold walls, twelve seconds later the hat exists. Machines took glass blowing away from human lungs in 1903.","stat":{"v":"12","u":"s","l":"per chimney, formed by air alone"},"call":[{"x":34,"y":44,"label":"The gather","sub":"180 g of glowing glass"},{"x":64,"y":56,"label":"Furnace mouth","sub":"where the gob parts company"}]},
  "candle-batch-03": {"h":"The Glass Batch","b":"Three parts sand, some soda ash, a pinch of lime, a fifth of it recycled cullet. The recipe is basically Rome's, and this chimney and your window share it.","stat":{"v":"72","u":"%","l":"of the batch is ordinary sand"},"call":[{"x":36,"y":44,"label":"Silica sand","sub":"72% of the batch"},{"x":86,"y":94,"label":"100 µm","sub":"one grain, measured"}]},
  "candle-quarry-04": {"h":"The Ground","b":"Ordinary quartz sand, washed until 98 percent pure. Let three hundredths of a percent of iron survive and the whole chimney turns green. This is a quarry that operates on hundredths.","stat":{"v":"0.03","u":"%","l":"iron allowed before green"},"call":[{"x":30,"y":38,"label":"The sand","sub":"almost pure silica"},{"x":62,"y":54,"label":"Stockpile","sub":"washed and graded"}]},
  "armchair-room": {"h":"The Room","b":"Two cane chairs wait against the wall, woven from a palm that climbs a hundred meters to the canopy. Follow the weave: palm, splitting machine, thirty-year tree.","stat":{"v":"7","u":"stops","l":"we end in a rattan grove"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "armchair-01": {"h":"A Rattan Armchair","b":"A teak skeleton, a woven palm skin, one cotton cushion. Six kilos of chair, rated for 120. The frame is glued, never screwed, and it will outlast this lease.","stat":{"v":"120","u":"kg","l":"carried by six kilos of chair"},"call":[{"x":36,"y":40,"label":"The webbing","sub":"hand-woven cane"},{"x":60,"y":62,"label":"The seat","sub":"built for 120 kg"}]},
  "armchair-cane-01": {"h":"The Cane Webbing","b":"Rattan peeled and split to six-millimeter strands, woven open so the back can breathe. It goes into the groove dry, gets pegged, and shrinks drum-tight as it dries. Your back rests on tension alone.","stat":{"v":"6","u":"mm","l":"strands of climbing palm"},"call":[{"x":34,"y":44,"label":"The strand","sub":"6 mm rattan peel"},{"x":64,"y":56,"label":"The octagon","sub":"woven under tension"}]},
  "armchair-frame-01": {"h":"The Teak Frame","b":"Kiln-dried teak, cut with mortise and tenon, glued and clamped by hand. The wood carries its own oil, so it shrugs off rot: shipwrights built entire navies on the same trick.","stat":{"v":"10","u":"%","l":"dried before the glue goes in"},"call":[{"x":47,"y":57,"label":"Mortise & tenon","sub":"pegged and glued"},{"x":56,"y":38,"label":"The weave","sub":"woven under tension"}]},
  "armchair-splitter-02": {"h":"The Splitting Machine","b":"Fresh-cut poles of climbing palm, 12 to 25 millimeters across, feed past a ring of blades and leave as even strands. Four to eight splits per pass, one and a half kilowatts doing the work of a hand knife.","stat":{"v":"1.5","u":"kW","l":"replacing the hand knife"},"call":[{"x":32,"y":44,"label":"Fresh-cut poles","sub":"12-25 mm across"},{"x":64,"y":56,"label":"The skin","sub":"peels off in strands"}]},
  "armchair-peels-03": {"h":"Rattan Peels","b":"The harvest is the palm's outer skin, split off a four-meter cane and sun-dried to twelve percent moisture. The same pole becomes garden canes, chair seats and walking sticks, graded at the bundling stage.","stat":{"v":"12","u":"%","l":"moisture when it leaves the yard"},"call":[{"x":34,"y":44,"label":"The peel","sub":"outer skin, coiled"},{"x":64,"y":58,"label":"The bundles","sub":"graded by diameter"}]},
  "armchair-grove-04": {"h":"The Ground","b":"A climbing palm hauls a hundred meters of hooked cane up to the light. It is cut like a crop, not felled: the clump keeps growing, the forest keeps standing. Nine tenths of the world's rattan works exactly like this.","stat":{"v":"7","u":"yr","l":"cut cycle, clump survives"},"call":[{"x":32,"y":42,"label":"The cane","sub":"climbing to light"},{"x":62,"y":56,"label":"The clump","sub":"keeps growing"}]},
  "insulated-bottle-room": {"h":"The Room","b":"On the shelf above the desk: the bottle that survived a car-park drop and still holds ice for a whole day. Between its walls, three millimeters of absolutely nothing. Pick it up.","stat":{"v":"6","u":"stops","l":"we end in an iron ore mine"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "insulated-bottle-01": {"h":"An Insulated Steel Bottle","b":"The object of the decade: forty ounces of steel that keeps ice for a day and coffee steaming on a cold walk. Between its walls is a three-millimeter gap of almost nothing, and a sun-hot beach never gets through it.","stat":{"v":"24","u":"h","l":"of cold behind a 3 mm gap"},"call":[{"x":50,"y":38,"label":"The wall","sub":"two skins, vacuum between"},{"x":34,"y":66,"label":"The boot","sub":"silicone, takes the drop"}]},
  "insulated-bottle-lid-01": {"h":"The Straw Lid","b":"The cap that sold the trend: molded polypropylene, a hinged spout, a floating straw ball that drinks from any angle, and a single silicone ring keeping all of it watertight.","stat":{"v":"2×","u":"","l":"bottle sales, 2021 to 2023"},"call":[{"x":44,"y":30,"label":"The cap","sub":"off, seal ring up"},{"x":47,"y":84,"label":"The ring","sub":"one molded silicone"}]},
  "insulated-bottle-press-02": {"h":"The Draw Press","b":"Flat sheet goes in, a vessel comes out: one stroke draws the cup from 304 coil, a redraw pass takes it to full height, and the metal thins by a tenth and hardens exactly where the wall needs it. Three hundred twenty tons, thirty strokes a minute.","stat":{"v":"320","u":"t","l":"drawing the shell in one stroke"},"call":[{"x":45,"y":62,"label":"The cup","sub":"drawn from flat sheet"},{"x":56,"y":30,"label":"The shell","sub":"taller after redraw"}]},
  "insulated-bottle-coil-03": {"h":"The Steel Coil","b":"Half a millimeter of 18/8 stainless: the chromium grows a rust-proof skin out of thin air, the nickel keeps it calm under the welding arc. Brearley was chasing rifle steel in 1913; cutlery won first.","stat":{"v":"18","u":"%","l":"chromium, 8% nickel beside it"},"call":[{"x":35,"y":40,"label":"The coil","sub":"18/8 stainless"},{"x":62,"y":60,"label":"The edge","sub":"0.5 mm, slit"}]},
  "insulated-bottle-ironmine-04": {"h":"The Ground","b":"Banded iron, blasted in benches, crushed and pelletized to sixty-two percent metal, railed out of a pit that deepens every year. Every gram of the bottle on the shelf was loose dirt here.","stat":{"v":"62","u":"%","l":"iron in the ore they haul"},"call":[{"x":31,"y":41,"label":"The face","sub":"blasted in benches"},{"x":62,"y":57,"label":"The ore","sub":"62 percent metal"}]},
  "wireless-earbuds-room": {"h":"The Room","b":"By the table sits a charging case the size of a soap bar, two earbuds snapped in and drawing nothing. Inside each bud: a speaker, a battery, a radio, a computer. Follow the sound backward and it ends in a copper pit and a lithium flat.","stat":{"v":"7","u":"stops","l":"we end in a copper pit"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "wireless-earbuds-01": {"h":"Wireless Earbuds","b":"One independent computer per ear: radio, codec, driver, microphones, battery. Apple shipped AirPods in 2016, and every component inside predates the category.","stat":{"v":"≈50","u":"mAh","l":"per ear, plus a bigger one in the case"},"call":[{"x":38,"y":56,"label":"The bud","sub":"a computer in your ear"},{"x":63,"y":68,"label":"The case","sub":"their home battery"}]},
  "wireless-earbuds-driver-01": {"h":"The Speaker Motor","b":"A cone the width of a pencil eraser, a copper voice coil, a neodymium ring. Push it, pull it, thousands of times a second. That push-pull is the whole sound.","stat":{"v":"8-13","u":"mm","l":"cone, pushed and pulled"},"call":[{"x":38,"y":48,"label":"The armature","sub":"the push"},{"x":59,"y":50,"label":"The coil","sub":"the field it rides"}]},
  "wireless-earbuds-cell-01": {"h":"The Button Cell","b":"Lithium ions shuttle between carbon and metal oxide, three to five hundred times, chemistry that took the 2019 Nobel for work done by 1991. Your buds and their case run the same science at different sizes.","stat":{"v":"300-500","u":"cycles","l":"before the chemistry retires"},"call":[{"x":36,"y":40,"label":"The 21700","sub":"the bigger chemistry"},{"x":68,"y":45,"label":"The 18650","sub":"the classic format"}]},
  "wireless-earbuds-coiler-02": {"h":"The Voice-Coil Winder","b":"A spinning spindle lays enameled copper finer than a hair under constant tension, hundreds of turns in seconds. Hand winding cannot hold the count. This machine guarantees no turn goes hungry.","stat":{"v":"0.03-0.05","u":"mm","l":"wire, thinner than hair"},"call":[{"x":46,"y":50,"label":"The spools","sub":"wire by the kilometer"},{"x":64,"y":46,"label":"The layers","sub":"spool on spool"}]},
  "wireless-earbuds-magnets-03": {"h":"Sintered NdFeB","b":"Alloy powder pressed inside a magnetic field, baked below melting until the grains fuse, cut, coated, magnetized. Sintered like porcelain and, gram for gram, the strongest magnet anyone sells.","stat":{"v":"1984","u":"","l":"invented, doubled every magnet before it"},"call":[{"x":38,"y":30,"label":"The field","sub":"iron dust traces it"},{"x":60,"y":55,"label":"The poles","sub":"sintered like porcelain"}]},
  "wireless-earbuds-coppermine-04": {"h":"The Ground","b":"Ore under one percent metal, Chuquicamata-class: terraces of rock hauled up for every coin of finished copper in the coil. This mine is where the story stops digging.","stat":{"v":"0.5-1","u":"%","l":"copper in the rock they haul"},"call":[{"x":33,"y":40,"label":"The benches","sub":"hauled rock, low grade"},{"x":61,"y":47,"label":"The pit floor","sub":"where every descent ends"}]},
  "matcha-whisk-room": {"h":"The Room","b":"Propped among the books: a whisk of bamboo tines, cut from one stem, bound with black thread. Its grove regrows in a single season. Follow it backward.","stat":{"v":"6","u":"stops","l":"we end in a bamboo grove"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "matcha-whisk-01": {"h":"Chasen (Bamboo Tea Whisk)","b":"One joint of bamboo, divided into fifty to a hundred and twenty tines. The outer skin stays where the shape should show, the lower rows get bound black to set the spring. Craft families in Nara have made it this way for five centuries, still entirely by hand.","stat":{"v":"50-120","u":"tines","l":"from one culm of bamboo"},"call":[{"x":48,"y":25,"label":"The bloom","sub":"flex tuned by taper"},{"x":52,"y":65,"label":"The binding","sub":"the hips hold it"}]},
  "matcha-whisk-tines-01": {"h":"The Tines","b":"Each tine gets skived thinner toward its tip, under one millimeter, so the whole head flexes as one instrument. Cut carelessly and it snaps or whips unevenly. Cut right, a hundred tines move like one finger.","stat":{"v":"1","u":"mm","l":"tip width, skived under"},"call":[{"x":45,"y":48,"label":"The fiber bundle","sub":"split, never sawn"},{"x":65,"y":40,"label":"The skin","sub":"kept for color"}]},
  "matcha-whisk-knot-01": {"h":"The Binding","b":"Black silk, wound in two bands around the lower rows, lifted with an awl, pulled tight, locked. It holds the pushed-up curve while the bamboo dries, then stays on for life. Unbound, a chasen relaxes and whips weak.","stat":{"v":"2","u":"bands","l":"of silk, locked for life"},"call":[{"x":42,"y":58,"label":"The hips","sub":"where spring is set"},{"x":60,"y":44,"label":"The knot","sub":"locked for life"}]},
  "matcha-whisk-splitter-02": {"h":"The Splitting Blade","b":"Industrial splitters ring a pole with blades for chopstick blanks. The whisk maker does the same division freehand with one curved knife, because the fiber bundle must stay joined at its base. Sawing would kill the grain.","stat":{"v":"1","u":"knife","l":"the whole split, done freehand"},"call":[{"x":44,"y":51,"label":"The blade ring","sub":"the industrial cousin"},{"x":63,"y":45,"label":"The pull","sub":"division without sawing"}]},
  "matcha-whisk-grove-04": {"h":"The Ground","b":"Bamboo hardens a stem to timber in one season, so the grove yields on a few-year rotation and the clump keeps coming back. This is the end of every descent here, and the quickest thing in the room to grow again.","stat":{"v":"3-5","u":"yr","l":"rotation, clump survives"},"call":[{"x":46,"y":38,"label":"The culms","sub":"cut at three years"},{"x":58,"y":62,"label":"The grove","sub":"yields on rotation"}]},
  "led-strip-room": {"h":"The Room","b":"Coiled in the drawer by the console: five meters of ribbon that glow and chase, one tile of light at a time. The crystal inside won the 2014 Nobel. Follow the glow backward and it ends in a copper pit an ocean away.","stat":{"v":"7","u":"stops","l":"we end in a copper mine"},"call":[{"x":52,"y":88,"label":"The desk","sub":"pick tonight's line"},{"x":60,"y":25,"label":"The lamp","sub":"light it up"}]},
  "led-strip-01": {"h":"LED Strip Light","b":"A flexible circuit dressed in tiles of light. Cut it anywhere on the marked edge and the remainder keeps dancing, because every tile carries its own driver chip. Addressable ribbons made the chasing effects.","stat":{"v":"30-96","u":"lights/m","l":"tiles of light, one chip each"},"call":[{"x":41,"y":54,"label":"The reel","sub":"5 meters, coiled"},{"x":62,"y":52,"label":"The cut line","sub":"cut anywhere"}]},
  "led-strip-emitter-01": {"h":"The LED Package","b":"A plastic package holding red, green and blue crystals, wired to share one cathode. Mix their currents and the tile is any color on the palette. Put a phosphor over blue and you get clean white.","stat":{"v":"5050","u":"SMD","l":"package class, RGB crystals inside"},"call":[{"x":44,"y":47,"label":"The dies","sub":"three chips inside"},{"x":55,"y":55,"label":"The glow","sub":"mixed into any color"}]},
  "led-strip-fpcb-01": {"h":"The Flex Circuit","b":"Under the lights: copper foil laminated to polyimide film, etched into tile after tile. It folds around furniture and carries the current headroom that keeps the far end of five meters from going dull.","stat":{"v":"1-2","u":"oz foil","l":"of copper, bent not broken"},"call":[{"x":44,"y":50,"label":"The traces","sub":"etched from foil"},{"x":63,"y":46,"label":"The board","sub":"copper, catching light"}]},
  "led-strip-smt-02": {"h":"The Placement Line","b":"The reel runs a placement line like any other board: paste printed on the pads, chips set to five-hundredths of a millimeter, flowed through one controlled temperature curve. Every tile gets tested before the reel ships.","stat":{"v":"245","u":"°C","l":"the peak of the reflow curve"},"call":[{"x":41,"y":46,"label":"The placement head","sub":"picks and sets"},{"x":66,"y":56,"label":"The reflow oven","sub":"bakes the curve"}]},
  "led-strip-copper-03": {"h":"The Copper Foil","b":"Rolled to kitchen-foil gauge, pure enough to etch clean, thin enough to flex ten thousand times, and still thick enough to carry five amps the length of five meters.","stat":{"v":"99.9","u":"%","l":"copper, foil-gauge"},"call":[{"x":45,"y":52,"label":"The spools","sub":"wire by the kilometer"},{"x":64,"y":48,"label":"The layers","sub":"spool on spool"}]},
  "led-strip-mine-04": {"h":"The Ground","b":"Ore under one percent metal, dug in terraced benches, floated, smelted, electrorefined to foil. The glow in this room started in a pit that ships its rock across an ocean. This is where the light begins.","stat":{"v":"125","u":"kg","l":"of rock per kilo of copper"},"call":[{"x":30,"y":38,"label":"The benches","sub":"roads cut in copper dirt"},{"x":56,"y":58,"label":"The pit lake","sub":"water in the hole"}]},
  "magnet-power-bank-room": {"h":"The Room","b":"On the settee cushion lies a black disk thinner than a wallet. Snap it to a phone and the magnets clamp, the coil lines up across a few millimeters of air, and it feeds. Follow the snap backward and you end at ore pits and a lithium flat.","stat":{"v":"7","u":"stops","l":"we end in a lithium flat"},"call":[{"x":52,"y":88,"label":"The desk","sub":"pick tonight's line"},{"x":60,"y":25,"label":"The lamp","sub":"light it up"}]},
  "magnet-power-bank-01": {"h":"Magnetic Power Bank","b":"It looks like nothing: a battery that snaps on. Inside: cells, a control board, a pancake coil, a ring of arc magnets negotiating with the phone the moment they touch. Snap-on charging became a category in late 2020 and never left.","stat":{"v":"10,000","u":"mAh","l":"in a wallet-thin shell"},"call":[{"x":35,"y":40,"label":"The bank","sub":"cells, board, coil in one shell"},{"x":63,"y":65,"label":"The phone","sub":"drawing current"}]},
  "magnet-power-bank-coil-01": {"h":"The Charging Coil","b":"Under the face sits a flat spiral of enameled copper. It pushes a field across millimeters of air and your phone's coil catches it. Alignment is everything, which is why the magnets exist.","stat":{"v":"2-8","u":"mm","l":"the gap where power crosses air"},"call":[{"x":46,"y":47,"label":"The spools","sub":"wire by the kilometer"},{"x":63,"y":52,"label":"The gap","sub":"where power crosses air"}]},
  "magnet-power-bank-board-01": {"h":"The Control Board","b":"Between the cells and the coil: battery guards, a charge controller that negotiates with the phone, wake circuitry that notices when something draws current. Without this board, charging is a fire risk. Every board gets tested.","stat":{"v":"1","u":"SoC","l":"running guards, wake and negotiation"},"call":[{"x":63,"y":50,"label":"The controller","sub":"one SoC, many jobs"},{"x":27,"y":45,"label":"The passives","sub":"keeping power clean"}]},
  "magnet-power-bank-smt-02": {"h":"The Placement Line","b":"The board itself comes off a placement line: paste printed, parts set by machine, flowed through one temperature curve, washed, tested. Every modern circuit rides these same machines.","stat":{"v":"245","u":"°C","l":"the peak of the reflow curve"},"call":[{"x":41,"y":46,"label":"The placement head","sub":"sets parts by the ten-thousands"},{"x":66,"y":56,"label":"The reflow oven","sub":"one curve, every board"}]},
  "magnet-power-bank-magnets-03": {"h":"Sintered NdFeB","b":"The ring's grip is sintered neodymium: alloy powder pressed under a magnetic field, baked until grains fuse, cut into arcs, magnetized in alternating directions. A few grams hold your phone against a case.","stat":{"v":"1984","u":"","l":"the year magnets doubled"},"call":[{"x":38,"y":30,"label":"The magnets","sub":"pressed like porcelain"},{"x":60,"y":55,"label":"The pull","sub":"arcs of it become the ring"}]},
  "magnet-power-bank-saltlake-04": {"h":"The Ground","b":"The cells drew their salt from brine pumped into sun ponds, or from spodumene crushed inland. The last stop of this line is a flat the size of a small country, drying six to eighteen months under nothing but sky. Then the salt feeds every pocket battery sold.","stat":{"v":"6-18","u":"mo","l":"of sun before the refinery"},"call":[{"x":40,"y":52,"label":"The flats","sub":"sun and salt, stage by stage"},{"x":65,"y":40,"label":"The ponds","sub":"orange steps to battery grade"}]},
  "slow-rebound-ball-room": {"h":"The Room","b":"Tucked into the armchair seat: a gray slow-rebound ball. Squeeze it and the dent holds. Let go and it crawls back over seconds. Follow the squeeze backward and you end at a wellhead of crude.","stat":{"v":"6","u":"stops","l":"we end in a crude oil well"},"call":[{"x":60,"y":25,"label":"The lamp","sub":"folds, aims, holds"},{"x":48,"y":62,"label":"This room","sub":"nineteen small machines"}]},
  "slow-rebound-ball-01": {"h":"Slow-Rebound Ball","b":"Cast polyurethane foam: two liquids poured shut, foaming against the mold walls with their own gas. Squeeze it and the cells collapse and vent. Let go and they crawl open. NASA tuned the chemistry for aircraft seats in 1966; the toy kept the bounce.","stat":{"v":"40-70","u":"mm","l":"ball that remembers for seconds"},"call":[{"x":48,"y":45,"label":"The ball","sub":"squeeze it, it remembers"},{"x":57,"y":45,"label":"The seam","sub":"the mold's parting line"}]},
  "slow-rebound-ball-mold-tooling": {"h":"The Mold","b":"The shell forms between metal halves: pour the reactive mix in, shut the tool, and the chemistry presses itself outward until the gas runs out and the skin sets. Every seam, vent and grain of texture lives inside these halves.","stat":{"v":"1","u":"ball","l":"per shearing of the halves"},"call":[{"x":43,"y":49,"label":"The cavity","sub":"where the foam grows"},{"x":62,"y":46,"label":"The parting line","sub":"every ball's seam"}]},
  "slow-rebound-ball-mill-02": {"h":"The Casting Line","b":"A metering head mixes the two streams at the face of a closed mold: liquid in, foam out, cured in minutes with the reaction itself as the furnace. Demold, wash, dry, paint, and the ball moves on.","stat":{"v":"5-15","u":"min","l":"in the mold, no furnace"},"call":[{"x":41,"y":49,"label":"The metering head","sub":"two streams, one mix"},{"x":60,"y":53,"label":"The mold","sub":"where the shot expands"}]},
  "slow-rebound-ball-foam-03": {"h":"The Foam Chemistry","b":"A polyol stirred with an isocyanate, water, catalysts and silicone stabilizer. The water makes the gas that blows the cells; the polyol blend picks how slowly the walls collapse and re-open. The squish is chosen in the formula.","stat":{"v":"2","u":"liquids","l":"and the recipe tunes the bounce"},"call":[{"x":44,"y":52,"label":"The pellets","sub":"metered like the recipe"},{"x":58,"y":57,"label":"The hand","sub":"measured out"}]},
  "slow-rebound-ball-oil-04": {"h":"The Ground","b":"Both streams begin as crude: drilled, refined, cracked, one route to the isocyanate, one to the polyol. The ball's whole body is petroleum rearranged into a slow spring. This well predates the foam by a century and feeds it all the same.","stat":{"v":"1859","u":"","l":"first commercial oil well"},"call":[{"x":40,"y":38,"label":"The rig","sub":"crude into polyol"},{"x":66,"y":56,"label":"The clearing","sub":"land that fed foam"}]},
  "mini-blender-room": {"h":"The Room","b":"On the round table by the window: a jar with a motor in its base and blades the size of a wine cork. Charge it over USB-C, spin it up, and fruit becomes smoothie where it stands. Follow the spin backward and you end in a pit and a wellhead.","stat":{"v":"7","u":"stops","l":"we end in a crude oil well"},"call":[{"x":52,"y":88,"label":"The desk","sub":"pick tonight's line"},{"x":60,"y":25,"label":"The lamp","sub":"light it up"}]},
  "mini-blender-01": {"h":"Mini Portable Blender","b":"Everything shares one bottle: the jar is the frame, the blades bolt to its base, and the motor, battery and board live inside. Press twice and the blades shear fruit in seconds. The drink never leaves the cup you drink from.","stat":{"v":"400-650","u":"ml","l":"jar, cup and bottle in one"},"call":[{"x":47,"y":45,"label":"The jar","sub":"cup and container in one"},{"x":63,"y":80,"label":"The base","sub":"motor, cell, board"}]},
  "mini-blender-motor-01": {"h":"The DC Motor","b":"Copper windings on an armature, spinning in a permanent-magnet field at around twenty thousand rpm. The physics is Stephen Poplawski's from 1922. What changed is the scale: a few dozen grams of motor now do a full blender's job.","stat":{"v":"20,000","u":"rpm","l":"from a few dozen grams"},"call":[{"x":42,"y":48,"label":"The armature","sub":"wound, balanced"},{"x":61,"y":50,"label":"The commutator","sub":"where current enters"}]},
  "mini-blender-blades-01": {"h":"The Blades","b":"The cutting is shear speed, not sharpness: four to six stamped stainless blades strike the fruit hundreds of times a second. Blanked in a press, curved once, weight-matched for spin so the bottle doesn't wobble.","stat":{"v":"4-6","u":"blades","l":"stamped, curved, matched"},"call":[{"x":45,"y":62,"label":"Stamped","sub":"blank to blade"},{"x":56,"y":30,"label":"The curve","sub":"formed in one pass"}]},
  "mini-blender-inj-02": {"h":"The Injection Molder","b":"Jar, cap and blade housing all come from a clamp and a hot mold. Clarity is the challenge: the jar shows a warp of a tenth of a millimeter in every pour, so the tooling and the cooling both have to be right.","stat":{"v":"80-150","u":"t","l":"of clamp, water-clear finish"},"call":[{"x":41,"y":48,"label":"The clamp","sub":"tons, shut"},{"x":61,"y":53,"label":"The eject","sub":"jar drops clear"}]},
  "mini-blender-pellets-03": {"h":"Tritan Pellets","b":"Clear pellets of Tritan copolyester arrive at the molder after a hard drying: any moisture left and the finished jar clouds. BPA-free, glass-clear, tough against a drop off the counter.","stat":{"v":"230","u":"°C","l":"the melt, after the drying"},"call":[{"x":45,"y":51,"label":"The pellets","sub":"dried before the melt"},{"x":59,"y":56,"label":"The clarity","sub":"glass-clear after molding"}]},
  "mini-blender-oil-04": {"h":"The Ground","b":"The jar's resin begins as crude: drilled, refined to naphtha, cracked into monomers, chained into copolyester. Blades, motor and battery carry their own mines. This stop ends the polymer line.","stat":{"v":"1859","u":"","l":"the well the jar's plastic drinks from"},"call":[{"x":40,"y":38,"label":"The rig","sub":"jar to well"},{"x":64,"y":58,"label":"The stump row","sub":"felled and hauled"}]},
  "portable-ssd-room": {"h":"The Room","b":"In the paper rack, standing like a letter among the pages: a pocket SSD. Two terabytes in a bar of aluminum that weighs nothing. Follow the files backward and every byte descends to a pit.","stat":{"v":"7","u":"stops","l":"we end in the bauxite pit"},"call":[{"x":52,"y":88,"label":"The desk","sub":"pick tonight's line"},{"x":60,"y":25,"label":"The lamp","sub":"light it up"}]},
  "portable-ssd-01": {"h":"Portable SSD","b":"Inside the shell: one bare M.2 board, a controller at one end, NAND dies beside it. No platters, no heads, no air cushion. The moving parts are gone, and the heat sink became the case.","stat":{"v":"2","u":"TB","l":"of flash, no moving parts"},"call":[{"x":25,"y":55,"label":"The label","sub":"the drive's birth certificate"},{"x":80,"y":30,"label":"Aluminum bar","sub":"the heatsink is the shell"}]},
  "portable-ssd-controller-01": {"h":"The Controller","b":"A small ARM-core computer with one job: pretending a shrinking, wear-prone NAND array is a uniform disk. It spreads writes, corrects errors, and keeps every logical block findable, in real time, for the life of the drive.","stat":{"v":"1","u":"SoC","l":"translating for terabytes"},"call":[{"x":63,"y":50,"label":"The controller","sub":"one chip, many jobs"},{"x":27,"y":45,"label":"The passives","sub":"keeping power clean"}]},
  "portable-ssd-nand-01": {"h":"The NAND Dies","b":"Bits are electric charge trapped on floating gates, stacked better than a hundred layers deep. That density is how half a terabyte fits on a postage stamp. Writing means erasing whole blocks first, and the controller keeps that ledger.","stat":{"v":"100","u":"+ layers","l":"stacked, three bits a cell"},"call":[{"x":44,"y":50,"label":"The board","sub":"controller and dies live here"},{"x":62,"y":47,"label":"The foil","sub":"etched from copper"}]},
  "portable-ssd-smt-02": {"h":"The Assembly Line","b":"Controller and NAND land on the board by machine: paste printed, parts placed at speed, the whole board reflowed in one pass, then washed, flashed and burned in before it ever sees a USB port.","stat":{"v":"0.05","u":"mm","l":"placement accuracy, every pad"},"call":[{"x":36,"y":20,"label":"The controller","sub":"set by machine"},{"x":61,"y":31,"label":"Every passive","sub":"placed to 0.05 mm"}]},
  "portable-ssd-alum-03": {"h":"The Aluminum Billet","b":"Aluminum enters the drive twice: the extruded case that doubles as a heat sink, and the metal-core board under the parts. Heat matters more than strength here, and the alloy carries it straight through.","stat":{"v":"150-200","u":"W/mK","l":"heat straight through the case"},"call":[{"x":43,"y":49,"label":"The core","sub":"metal as a heat spread"},{"x":62,"y":47,"label":"The traces","sub":"copper on insulation"}]},
  "portable-ssd-bauxite-04": {"h":"The Ground","b":"Red laterite, mined in benches, refined to alumina the Bayer way, split into metal near 950 °C in an electrolytic pot. Every kilogram of this case carries roughly fifteen kilowatt-hours of electricity on its back. That is the bill for a rock turned heatsink.","stat":{"v":"15","u":"kWh/kg","l":"of electricity, carried forever"},"call":[{"x":42,"y":44,"label":"The core","sub":"bauxite, unweathered"},{"x":70,"y":28,"label":"The ore","sub":"your case, pre-travel"}]},
  "ballpoint-pen-room": {"h":"The Room","b":"Lying across the book on the coffee table: a twist-action ballpoint. Nobody notices pens anymore, which is the measure of how good they got. Follow the rolling ball backward and you end at iron ore in terraced benches.","stat":{"v":"7","u":"stops","l":"we end in iron ore benches"},"call":[{"x":52,"y":88,"label":"The desk","sub":"pick tonight's line"},{"x":60,"y":25,"label":"The lamp","sub":"light it up"}]},
  "ballpoint-pen-01": {"h":"Ballpoint Pen","b":"A sealed refill, a return spring, and a carbide ball at the tip rolling ink onto paper. Bíró escaped Hungary in 1940 and the RAF bought thousands. The cheap descendant, the Bic Cristal of 1950, has sold over a hundred billion.","stat":{"v":"100","u":"billion","l":"sold since 1950"},"call":[{"x":40,"y":43,"label":"The refill","sub":"ink paste, sealed"},{"x":63,"y":58,"label":"The tip","sub":"brass, holding the ball"}]},
  "ballpoint-pen-ball-01": {"h":"The Carbide Ball","b":"Tungsten-cemented carbide, sintered to near-glass hardness and ground to roundness within about a micron. It rolls down the socket lip, shears clean on the way past, and meters the ink in exactly the film the ride allows.","stat":{"v":"1","u":"µm","l":"roundness on a pin's head"},"call":[{"x":30,"y":44,"label":"The ball","sub":"ground within a micron"},{"x":52,"y":44,"label":"The socket","sub":"ink meters past it"}]},
  "ballpoint-pen-spring-01": {"h":"The Return Spring","b":"A stainless compression spring between the refill's collar and the stop: press the nib and the ball clears, release and the refill floats free until the twist clamps it. The spring's rate is the pen's whole personality, repeated for years.","stat":{"v":"10k+","u":"","l":"cycles, spec says tens of thousands"},"call":[{"x":44,"y":50,"label":"The coils","sub":"wound to a rate"},{"x":61,"y":52,"label":"The wire","sub":"drawn to gauge"}]},
  "ballpoint-pen-grinder-02": {"h":"The Ball Grinder","b":"Balls are ground by the thousand: rough blanks rolled between plates until roundness becomes a number on a certificate, then graded by size into tip batches. Bearing-grade precision, borrowed for pens.","stat":{"v":"0.001","u":"mm","l":"sub-micron round tolerance"},"call":[{"x":88,"y":28,"label":"The control","sub":"cut by numbers"},{"x":17,"y":72,"label":"The bins","sub":"blanks queued in batches"}]},
  "ballpoint-pen-carbide-03": {"h":"Tungsten Carbide","b":"Gray tungsten carbide and cobalt powder, pressed into blanks, pre-sintered, then baked in vacuum near fourteen hundred degrees until it densifies. Its hardness rides just under diamond, which is why it rolls and never flattens.","stat":{"v":"1,400","u":"°C","l":"in vacuum, near diamond hardness"},"call":[{"x":45,"y":25,"label":"The tools","sub":"sintered, near diamond"},{"x":52,"y":53,"label":"One powder","sub":"many tools"}]},
  "ballpoint-pen-mine-04": {"h":"The Ground","b":"Benches cut into iron ore, hauled by the truckload, burned with coke in a blast furnace, cast into billets, drawn into the wire of every spring in every pen. The pit in this photo opened in the 1890s and never stopped feeding steel.","stat":{"v":"55-67","u":"%","l":"iron in the rock they haul"},"call":[{"x":34,"y":41,"label":"The benches","sub":"hauled, one cut at a time"},{"x":61,"y":47,"label":"The trucks","sub":"ore by the truckload"}]}
};
